INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(31711, 'John 16:18', 'John', 16, 18, 'هغوی وویل: «د دې لږې مودې نه چې عیسی د هغې په هکله خبرې کوي مقصد څه دی؟ مونږ نه پوهېږو چې هغه د څه شي په هکله خبرې کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_18.mp3', '', 1761754199, 1761754199),
(31712, 'John 16:19', 'John', 16, 19, 'عیسی پوه شو چې هغوی غواړي په دې هکله ترې پوښتنه وکړي، نو هغوی ته یې وویل: «ایا تاسو په دې خاطر د یو بل نه پوښتنه کوئ چې زما د دې خبرې نه مقصد څه دی چې تاسو به د لږ وخت دپاره نور ما ونه وینئ، خو لږه موده وروسته به بیا ما ووینئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_19.mp3', '', 1761754199, 1761754199),
(31713, 'John 16:20', 'John', 16, 20, 'په یقین سره زه تاسو ته دا وایم چې تاسو به ژاړئ او ویر به کوئ خو نړۍ به خوشحاله وي. تاسو به غمجن یئ، خو ستاسو غم به په خوشحالۍ بدل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_20.mp3', '', 1761754199, 1761754199),
(31714, 'John 16:21', 'John', 16, 21, 'یوه ښځه د ماشوم د زېږولو په وخت کې ډېر دردونه زغمي، خو کله چې ماشوم پیدا شي، نو هغه خپل دردونه هېروي، ځکه چې هغه خوشحاله وي چې یو انسان یې نړۍ ته راوړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_21.mp3', '', 1761754199, 1761754199),
(31715, 'John 16:22', 'John', 16, 22, 'تاسو هم اوس غمجن یئ، خو زه به بیا تاسو ووینم او زړونه به مو خوشحاله شي او هېڅوک نه شي کولای چې دا خوشحالي ستاسو نه واخلي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_22.mp3', '', 1761754199, 1761754199),
(31716, 'John 16:23', 'John', 16, 23, 'کله چې هغه ورځ راشي نو تاسو به زما نه هېڅ سوال نه کوئ. په یقین سره زه تاسو ته دا وایم چې که چېرې تاسو زما په نوم د پلار نه هرڅه وغواړئ نو تاسو ته به یې درکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_23.mp3', '', 1761754199, 1761754199),
(31717, 'John 16:24', 'John', 16, 24, 'تر‌اوسه پورې تاسو زما په نوم هېڅ شی نه دی غوښتی، وغواړئ نو تاسو ته به درکړل شي، ترڅو ستاسو خوشحالي پوره شي. په نړۍ باندې بری موندل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_24.mp3', '', 1761754199, 1761754199),
(31718, 'John 16:25', 'John', 16, 25, 'ما تاسو ته په مثالونو کې خبرې کولې، خو داسې وخت به راشي چې نور به تاسو ته په مثالونو کې خبرې نه کوم، بلکې په ښکاره توګه به تاسو ته د پلار په هکله خبرې کوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_25.mp3', '', 1761754199, 1761754199),
(31719, 'John 16:26', 'John', 16, 26, 'کله چې هغه ورځ راشي نو تاسو به زما په نوم هغه ته سوال کوئ او ماته به د دې اړتیا نه وي چې ستاسو په خاطر هغه ته خواست وکړم،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_26.mp3', '', 1761754199, 1761754199),
(31720, 'John 16:27', 'John', 16, 27, 'ځکه چې پلار په خپله تاسو سره مینه لري. ځکه چې تاسو ما سره مینه کوئ او په دې باندې تاسو ایمان راوړی دی چې زه د خدای له خوا راغلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_27.mp3', '', 1761754199, 1761754199),
(31721, 'John 16:28', 'John', 16, 28, 'زه د پلار له خوا دې نړۍ ته راغلی یم او اوس نړۍ پرېږدم او پلار ته ورځم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_28.mp3', '', 1761754199, 1761754199),
(31722, 'John 16:29', 'John', 16, 29, 'بیا د عیسی شاګردانو وویل: «ته اوس ښکاره خبرې کوې او د مثالونو نه کار نه اخلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_29.mp3', '', 1761754199, 1761754199),
(31723, 'John 16:30', 'John', 16, 30, 'اوس مونږ پوهېږو چې ته د هرڅه نه خبر یې او لازمه نه ده چې کوم څوک ستا نه د کوم شي په هکله پوښتنه وکړي. نو له همدې امله مونږ ایمان لرو چې ته د خدای له خوا راغلی یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_30.mp3', '', 1761754199, 1761754199),
(31724, 'John 16:31', 'John', 16, 31, 'عیسی هغوی ته وویل: «ایا تاسو اوس په ما باندې پوره ایمان لرئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_31.mp3', '', 1761754199, 1761754199),
(31725, 'John 16:32', 'John', 16, 32, 'ګورئ، هغه وخت راروان دی او بلکې رارسېدلی دی چې تاسو ټول به خواره واره شئ او خپلو کورونو ته به لاړ شئ او ما به یوازې پرېږدئ. خو بیاهم زه یوازې نه یم، ځکه چې پلار راسره دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_32.mp3', '', 1761754199, 1761754199),
(31726, 'John 16:33', 'John', 16, 33, 'ما دا هرڅه د دې دپاره تاسو ته وویل ترڅو په ما کې ارامي ولرئ. په دې نړۍ کې به تاسو ځورېږئ او کړېږئ. خو زړور اوسئ! ځکه چې زه په نړۍ باندې بریالی شوی یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john16_verse_33.mp3', '', 1761754199, 1761754199),
(31727, 'Romans 10:1', 'Romans', 10, 1, 'ای خویندو او ورونو! زما د زړه غوښتنه او خدای ته دا دعا ده چې زما قوم خلاصون ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_1.mp3', '', 1761754199, 1761754199),
(31728, 'Romans 10:2', 'Romans', 10, 2, 'زه په دې شاهدي ورکوم چې هغوی د خدای په هکله غیرتي دي، خو د هغوی غیرت د پوهې له مخې نه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_2.mp3', '', 1761754199, 1761754199),
(31729, 'Romans 10:3', 'Romans', 10, 3, 'ځکه چې هغوی هغه لاره ونه پېژندله چې خدای د هغې په وسیله خلک په خپل حضور کې عادلان ګڼي او د هغه په ځای کوښښ یې وکړ چې خپله لاره عادلانه وښایي او په دې ډول هغوی د خدای د عدالت تابعداري نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_3.mp3', '', 1761754199, 1761754199),
(31730, 'Romans 10:4', 'Romans', 10, 4, 'ځکه چې مسیح د شریعت پوره کوونکی دی، نو هرڅوک چې په هغه باندې ایمان راوړي، هغوی به د خدای په حضور کې عادلان وګڼل شي. ټولو ته د ژغورنې پیغام', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_4.mp3', '', 1761754199, 1761754199),
(31731, 'Romans 10:5', 'Romans', 10, 5, 'موسی د عادل کېدلو په هکله چې د شریعت په وسیله تر‌لاسه کیږي، لیکي: «څوک چې په شریعت باندې عمل کوي، نو د هغه په وسیله به ژوند کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_5.mp3', '', 1761754199, 1761754199),
(31732, 'Romans 10:6', 'Romans', 10, 6, 'خو د هغه عدالت په هکله چې د ایمان په وسیله تر‌لاسه کیږي، وایي: «په خپل زړه کې داسې مه وایئ: ‹څوک به اسمان ته وخېژي؟› د دې دپاره چې مسیح لاندې راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_6.mp3', '', 1761754199, 1761754199),
(31733, 'Romans 10:7', 'Romans', 10, 7, 'یا داسې مه وایئ: ‹څوک کولای شي چې ښکته د مړو دنیا ته لاړ شي؟› د دې دپاره چې مسیح د مړو نه راژوندی کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_7.mp3', '', 1761754199, 1761754199),
(31734, 'Romans 10:8', 'Romans', 10, 8, 'د خدای کلام څه وایي؟ د خدای پیغام تا سره نژدې دی. هغه ستا په خوله او ستا په زړه کې دی. هغه پیغام د ایمان پیغام دی چې مونږ یې اعلانوو:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_8.mp3', '', 1761754199, 1761754199),
(31735, 'Romans 10:9', 'Romans', 10, 9, 'که چېرې ته په خپله خوله اقرار وکړې چې عیسی څښتن دی او په خپل زړه کې په دې ایمان ولرې چې خدای هغه د مړو نه راژوندی کړی دی، نو ته به خلاصون ومومې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_9.mp3', '', 1761754199, 1761754199),
(31736, 'Romans 10:10', 'Romans', 10, 10, 'ځکه که څوک د زړه نه ایمان راوړي، نو هغه به نېک وګڼل شي او که په خپله خوله د خپل ایمان اقرار وکړي، نو هغه به خلاصون ومومي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_10.mp3', '', 1761754199, 1761754199),
(31737, 'Romans 10:11', 'Romans', 10, 11, 'د پیغمبرانو په لیکنو کې ویل شوي دي: «هرڅوک چې په هغه باندې ایمان راوړي، نو هېڅکله به ونه شرمیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_11.mp3', '', 1761754199, 1761754199),
(31738, 'Romans 10:12', 'Romans', 10, 12, 'نو ځکه د یهودي او غیریهودي ترمنځ هېڅ فرق نشته، ځکه چې د ټولو څښتن یو دی او هغو ټولو کسانو ته چې د هغه نه مرسته غواړي، زیات برکتونه ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_12.mp3', '', 1761754199, 1761754199),
(31739, 'Romans 10:13', 'Romans', 10, 13, 'لکه څنګه چې د خدای کلام وایي: «هرڅوک چې د څښتن په نوم مرسته وغواړي، نو هغه به وژغورل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_13.mp3', '', 1761754199, 1761754199),
(31740, 'Romans 10:14', 'Romans', 10, 14, 'خو که چېرې هغوی په هغه باندې ایمان نه وي راوړی، نو څنګه به هغه ته اواز وکړي او مرسته به ورڅخه وغواړي؟ او څنګه کولای شي چې په هغه باندې ایمان راوړي چې د هغه په هکله یې څه نه وي اورېدلي؟ او هغوی به یې څنګه واوري ترڅو چې چا ورته پیغام نه وي رسولی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_14.mp3', '', 1761754199, 1761754199),
(31741, 'Romans 10:15', 'Romans', 10, 15, 'او هغوی به څنګه پیغام ورسوي، ترڅو د دې کار دپاره لېږل شوي نه وي؟ لکه څنګه چې د خدای په کلام کې لیکل شوي دي: څومره ښکلي دي د پیغام وړونکي قدمونه چې زېری رسوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_15.mp3', '', 1761754199, 1761754199),
(31742, 'Romans 10:16', 'Romans', 10, 16, 'خو هغوی ټولو هغه زېری قبول نه کړ، ځکه اشعیا نبي وایي: «ای څښتنه، چا زمونږ په پیغام باندې باور کړی دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_16.mp3', '', 1761754199, 1761754199),
(31743, 'Romans 10:17', 'Romans', 10, 17, 'نو ایمان د پیغام په اورېدلو سره پیدا کیږي او پیغام د مسیح د کلام په وسیله اورېدل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_17.mp3', '', 1761754199, 1761754199),
(31744, 'Romans 10:18', 'Romans', 10, 18, 'خو زه پوښتنه کوم چې ایا د اسراییلو قوم پیغام نه دی اورېدلی؟ بې له شکه چې اورېدلی یې دی، ځکه لکه څنګه چې د خدای کلام وایي: د زیري رسوونکو اواز په ټوله دنیا کې اورېدل کیږي او د هغوی خبرې د دنیا تر بل سره پورې رسیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_18.mp3', '', 1761754199, 1761754199),
(31745, 'Romans 10:19', 'Romans', 10, 19, 'خو زه یوځل بیا پوښتنه کوم چې ایا د اسراییلو خلک په دې پوه نه شول؟ موسی لومړنی کس دی چې وایي: زه به په تاسو کې د هغو خلکو په وسیله بخیلي پیدا کړم چې په قوم کې نه شمېرل کیږي او د یو نا پوهه قوم په وسیله به ستاسو قهر راوپاروم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_19.mp3', '', 1761754199, 1761754199),
(31746, 'Romans 10:20', 'Romans', 10, 20, 'بیا اشعیا په ډېرې زړورتیا سره وایي: زه هغو خلکو پیدا کړم چې زما په لټه کې نه وو او خپل ځان مې هغو خلکو ته ښکاره کړ چې زه یې نه غوښتلم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_20.mp3', '', 1761754199, 1761754199),
(31747, 'Romans 10:21', 'Romans', 10, 21, 'خو د اسراییلو د قوم په هکله خدای وایي: ټوله ورځ مې هغو خلکو ته د پخلاینې دپاره غېږه خلاصه کړې وه چې نافرمانه او سرکښه وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans10_verse_21.mp3', '', 1761754199, 1761754199),
(31748, 'John 21:1', 'John', 21, 1, 'څه موده وروسته عیسی یوځل بیا د تبریې د بحیرې په غاړه شاګردانو ته خپل ځان ښکاره کړ. هغه خپل ځان په دې ډول ښکاره کړ:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john21_verse_1.mp3', '', 1761754199, 1761754199),
(31749, 'John 21:2', 'John', 21, 2, 'شمعون پطروس او توما چې د غبرګوني په نوم یادېده، نتناییل چې د جلیل د قانا څخه ؤ، د زبدي دوه زامن او دوه نور شاګردان هم هلته وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john21_verse_2.mp3', '', 1761754199, 1761754199),
(31750, 'John 21:3', 'John', 21, 3, 'شمعون پطروس هغوی ته وویل: «زه ځم چې ماهیان ونیسم.» هغوی وویل: «مونږ هم درسره ځو.» هغوی روان شول او په کشتۍ کې سپاره شول، خو په هغه شپه یې هېڅ ونه نیول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john21_verse_3.mp3', '', 1761754199, 1761754199),
(31751, 'John 21:4', 'John', 21, 4, 'کله چې سهار شو نو عیسی د بحیرې په غاړه ولاړ ؤ، خو شاګردانو ونه پېژانده چې هغه عیسی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john21_verse_4.mp3', '', 1761754199, 1761754199),
(31752, 'John 21:5', 'John', 21, 5, 'عیسی هغوی ته نارې کړې: «ای ملګرو، کوم څه مو نیولي دي؟» هغوی ځواب ورکړ: «نه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john21_verse_5.mp3', '', 1761754199, 1761754199),
(31753, 'John 21:6', 'John', 21, 6, 'عیسی هغوی ته وویل: «خپل جال مو د کشتۍ ښي خواته ورواچوئ نو یو څه ماهیان به ونیسئ.» نو هغوی جال ورواچاوه او دومره ډېر ماهیان یې ونیول چې دوی نه شو کولای چې جال بېرته کشتۍ ته راکاږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john21_verse_6.mp3', '', 1761754199, 1761754199),
