(31794, 'John 6:22', 'John', 6, 22, 'بله ورځ هغه خلک چې د بحیرې په بله غاړه ولاړ وو ولیدل چې هلته یوازې یوه کشتۍ وه او عیسی په کې د خپلو شاګردانو سره نه ؤ ختلی، بلکې هغوی یوازې تللي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_22.mp3', '', 1761754199, 1761754199),
(31795, 'John 6:23', 'John', 6, 23, 'بیا د تبریې د ښار څخه نورې کشتۍ هغه ځای ته راورسېدلې چې خلکو په کې هغه ډوډۍ خوړلې وه چې عیسی ورباندې د خدای شکر ویستلی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_23.mp3', '', 1761754199, 1761754199),
(31796, 'John 6:24', 'John', 6, 24, 'نو کله چې خلکو ولیدل چې هلته نه عیسی ؤ او نه یې شاګردان، نو هغوی په کشتۍ کې سپاره شول او د عیسی د لټولو دپاره کپرناحوم ته لاړل. عیسی د ژوندون ډوډۍ ده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_24.mp3', '', 1761754199, 1761754199),
(31797, 'John 6:25', 'John', 6, 25, 'کله چې خلکو عیسی د بحیرې په بله غاړه پیدا کړ نو ورته ویې ویل: «استاذه، ته کله دلته راورسېدلې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_25.mp3', '', 1761754199, 1761754199),
(31798, 'John 6:26', 'John', 6, 26, 'عیسی ځواب ورکړ: «په یقین سره زه تاسو ته دا وایم چې تاسو د دې دپاره ما نه لټوئ چې زما معجزې مو لیدلي دي بلکې د هغه ډوډۍ په خاطر چې ومو خوړله او ماړه شوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_26.mp3', '', 1761754199, 1761754199),
(31799, 'John 6:27', 'John', 6, 27, 'د فاني خوړو دپاره خواري مه کوئ بلکې د هغو خوړو دپاره خواري وکړئ چې د تلپاتې ژوندون پورې پاتې کیږي، یعنې هغه خواړه چې د انسان زوی به یې تاسو ته درکوي. ځکه چې پلار خدای هغه ته اختیار ورکړی دی چې داسې وکړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_27.mp3', '', 1761754199, 1761754199),
(31800, 'John 6:28', 'John', 6, 28, 'بیا خلکو پوښتنه وکړه: «مونږ څه وکړو، ترڅو هغه کارونه چې خدای یې زمونږ نه غواړي سرته ورسوو؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_28.mp3', '', 1761754199, 1761754199),
(31801, 'John 6:29', 'John', 6, 29, 'عیسی په ځواب کې وویل: «کوم کار چې خدای یې ستاسو څخه غواړي هغه دا دی چې په هغه چا باندې ایمان راوړئ چې هغه رالېږلی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_29.mp3', '', 1761754199, 1761754199),
(31802, 'John 6:30', 'John', 6, 30, 'نو هغوی وویل: «ته مونږ ته کومه معجزه ښکاره کوې چې مونږ یې ووینو او ایمان درباندې راوړو؟ ته به څه کار وکړې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_30.mp3', '', 1761754199, 1761754199),
(31803, 'John 6:31', 'John', 6, 31, 'زمونږ نیکونو په دښته کې د من ډوډۍ وخوړله او لکه څنګه چې د خدای په کلام کې لیکل شوي دي: هغه د اسمان نه هغوی ته ډوډۍ ورکړه چې ویې خوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_31.mp3', '', 1761754199, 1761754199),
(31804, 'John 6:32', 'John', 6, 32, 'عیسی هغوی ته وویل: «په یقین سره زه تاسو ته دا وایم چې دا موسی نه ؤ چې تاسو ته یې د اسمان نه ډوډۍ درکړله بلکې زما پلار درکوله او اوس هغه تاسو ته د اسمان څخه رښتینې ډوډۍ درکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_32.mp3', '', 1761754199, 1761754199),
(31805, 'John 6:33', 'John', 6, 33, 'ځکه کومه ډوډۍ چې خدای یې درکوي هغه د اسمان څخه رانازلیږي او نړۍ ته ژوندون ورکوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_33.mp3', '', 1761754199, 1761754199),
(31806, 'John 6:34', 'John', 6, 34, 'هغوی وویل: «ښاغلیه، مونږ ته تل دغه ډوډۍ راکوه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_34.mp3', '', 1761754199, 1761754199),
(31807, 'John 6:35', 'John', 6, 35, 'عیسی هغوی ته وویل: «زه هغه ډوډۍ یم چې ژوندون ورکوي. څوک چې ماته راځي هغه به هېڅکله نه وږی کیږي او څوک چې په ما باندې ایمان راوړي هغه به هېڅکله نه تږی کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_35.mp3', '', 1761754199, 1761754199),
(31808, 'John 6:36', 'John', 6, 36, 'خو لکه څنګه چې ما وویل چې سره له دې چې تاسو زه لیدلی یم خو بیاهم په ما باندې ایمان نه راوړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_36.mp3', '', 1761754199, 1761754199),
(31809, 'John 6:37', 'John', 6, 37, 'کوم خلک چې زما پلار یې ماته راکوي هغوی به ماته راځي او څوک چې ماته راځي زه به هغه هېڅکله ونه شړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_37.mp3', '', 1761754199, 1761754199),
(31810, 'John 6:38', 'John', 6, 38, 'ځکه چې زه د اسمان نه د دې دپاره نه یم راښکته شوی چې خپله رضا پوره کړم بلکې د دې دپاره چې د هغه چا رضا پوره کړم چې زه یې رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john6_verse_38.mp3', '', 1761754199, 1761754199);